with seed(slug,chapter_slug,topic,subtopic,fact,difficulty,tags) as (values
('physics-coulomb-law-01','electricity','Electrostatics','Coulomb law','The electrostatic force between two point charges is proportional to the product of their charges and inversely proportional to the square of their separation.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-electric-field-flux-01','electricity','Electrostatics','Electric field and flux','Electric flux through a surface is the surface integral of the electric field component normal to that surface.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-gauss-law-01','electricity','Electrostatics','Gauss law','The net electric flux through a closed surface equals the enclosed charge divided by the permittivity of free space.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-electric-potential-01','electricity','Electrostatics','Electric potential','Electric potential is potential energy per unit positive test charge and its negative gradient gives the electric field.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-electric-dipoles-01','electricity','Electrostatics','Dipoles','An electric dipole consists of equal and opposite charges separated by a small distance, with moment directed from negative to positive charge.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-capacitance-dielectrics-01','electricity','Electrostatics','Capacitance and dielectrics','Capacitance is charge stored per unit potential difference, and inserting a dielectric increases it by the relative permittivity for full filling.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-drift-velocity-01','electricity','Current electricity','Drift velocity','Electric current in a conductor equals charge-carrier number density times charge, cross-sectional area and drift velocity.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-ohm-law-01','electricity','Current electricity','Ohm law','At constant physical conditions, the current through an ohmic conductor is directly proportional to the potential difference across it.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-resistivity-01','electricity','Current electricity','Resistivity','For a uniform wire, resistance equals resistivity times length divided by cross-sectional area.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-series-parallel-circuits-01','electricity','Current electricity','Series and parallel circuits','Resistances add directly in series, while conductances add for resistors connected in parallel.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-kirchhoff-laws-01','electricity','Current electricity','Kirchhoff laws','Kirchhoff junction and loop rules express conservation of charge and conservation of energy in electrical circuits.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-cells-01','electricity','Current electricity','Cells','A cell of emf E and internal resistance r delivering current I has terminal voltage E minus Ir.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-wheatstone-bridge-01','electricity','Current electricity','Wheatstone bridge','A Wheatstone bridge is balanced when the ratios of resistances in its two arms are equal, producing zero galvanometer current.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-potentiometer-01','electricity','Current electricity','Potentiometer','A potentiometer compares emfs by balancing them against potential drops along a uniform wire without drawing current at balance.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-biot-savart-01','magnetism','Magnetic effects of current','Biot-Savart law','The Biot-Savart law gives the magnetic-field contribution of a current element, proportional to current and the sine of the angle and inversely proportional to distance squared.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-ampere-law-01','magnetism','Magnetic effects of current','Ampere law','The circulation of magnetic field around a closed path equals permeability times the current enclosed by that path.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-force-charge-01','magnetism','Magnetic effects of current','Force on a charge','A charge q moving with velocity v in magnetic field B experiences force q times v cross B, perpendicular to both v and B.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-force-conductor-01','magnetism','Magnetic effects of current','Force on a conductor','A straight current-carrying conductor of vector length L in magnetic field B experiences force I times L cross B.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-cyclotron-01','magnetism','Magnetic effects of current','Cyclotron','A cyclotron accelerates charged particles using an alternating electric field while a perpendicular magnetic field bends them into semicircles.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-galvanometer-01','magnetism','Magnetic effects of current','Galvanometer','A moving-coil galvanometer detects small currents by balancing magnetic torque against the restoring torque of its suspension.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-bar-magnet-01','magnetism','Magnetism and matter','Bar magnet','A bar magnet behaves approximately as a magnetic dipole with field lines emerging from its north pole and entering its south pole externally.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-magnetic-dipole-01','magnetism','Magnetism and matter','Magnetic dipole','The magnetic dipole moment of a planar current loop equals current times its vector area.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-earth-magnetism-01','magnetism','Magnetism and matter','Earth magnetism','The Earth behaves approximately like a tilted magnetic dipole, described locally by declination, dip and horizontal field component.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-magnetic-materials-01','magnetism','Magnetism and matter','Dia-, para- and ferromagnetism','Diamagnetic materials are weakly repelled, paramagnetic materials weakly attracted and ferromagnetic materials strongly magnetised by an applied field.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-magnetic-flux-01','magnetism','Electromagnetic induction','Magnetic flux','Magnetic flux is the surface integral of the magnetic field component normal to a surface.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-faraday-lenz-01','magnetism','Electromagnetic induction','Faraday and Lenz laws','Induced emf equals the negative time rate of change of magnetic flux linkage, with the sign expressing opposition to the change.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-motional-emf-01','magnetism','Electromagnetic induction','Motional emf','A conductor moving through a magnetic field develops motional emf from the magnetic force on its mobile charges.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-inductance-01','magnetism','Electromagnetic induction','Inductance','Inductance measures flux linkage per unit current and produces an emf opposing the rate of change of current.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-eddy-currents-01','magnetism','Electromagnetic induction','Eddy currents','Eddy currents are closed currents induced in bulk conductors by changing magnetic flux and can cause heating and magnetic braking.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-ac-generator-01','magnetism','Electromagnetic induction','AC generator','An AC generator converts mechanical energy to alternating electrical energy by rotating a coil in a magnetic field.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-ac-phasors-01','magnetism','Alternating current','Phasors','Phasors represent sinusoidally varying quantities as rotating vectors, making phase relations and AC addition easier to analyse.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-rlc-circuits-01','magnetism','Alternating current','RLC circuits','In a series RLC circuit, impedance combines resistance with the net reactance equal to inductive reactance minus capacitive reactance.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-ac-resonance-01','magnetism','Alternating current','Resonance','Series AC resonance occurs when inductive and capacitive reactances are equal, making impedance minimum and current maximum.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-power-factor-01','magnetism','Alternating current','Power factor','The AC power factor is the cosine of the phase difference between voltage and current and equals resistance divided by impedance in a series circuit.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-transformers-01','magnetism','Alternating current','Transformers','An ideal transformer changes AC voltage in the turns ratio while conserving input and output power.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-displacement-current-01','magnetism','Electromagnetic waves','Displacement current','Displacement current is associated with a changing electric flux and completes Ampere law in regions such as a capacitor gap.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-em-wave-properties-01','magnetism','Electromagnetic waves','Wave properties','Electromagnetic waves are transverse, need no material medium and have mutually perpendicular electric and magnetic fields.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-em-spectrum-01','magnetism','Electromagnetic waves','Electromagnetic spectrum','The electromagnetic spectrum is ordered by frequency or wavelength from radio waves through microwaves, infrared, visible, ultraviolet, X-rays and gamma rays.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-optics-reflection-01','optics','Ray optics','Reflection','The law of reflection states that the angle of incidence equals the angle of reflection and all three relevant lines are coplanar.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-spherical-mirrors-01','optics','Ray optics','Spherical mirrors','For paraxial rays, a spherical mirror has focal length equal to half its radius of curvature.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-optics-refraction-01','optics','Ray optics','Refraction','Snell law states that the ratio of sines of the incidence and refraction angles equals the relative refractive index.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-total-internal-reflection-01','optics','Ray optics','Total internal reflection','Total internal reflection occurs for light travelling from a denser to a rarer medium when incidence exceeds the critical angle.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-lenses-01','optics','Ray optics','Lenses','For a thin lens in air, reciprocal focal length equals reciprocal image distance minus reciprocal object distance under the Cartesian sign convention.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-prisms-01','optics','Ray optics','Prisms','At minimum deviation through a prism, the light path is symmetric and the incidence and emergence angles are equal.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-optical-instruments-01','optics','Ray optics','Optical instruments','Optical instruments combine lenses or mirrors to increase angular size, form resolved images or collect more light.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-huygens-principle-01','optics','Wave optics','Huygens principle','Every point on a wavefront acts as a source of secondary wavelets whose envelope forms the next wavefront.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-interference-01','optics','Wave optics','Interference','Interference is the redistribution of intensity produced when coherent waves superpose with stable phase difference.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-young-double-slit-01','optics','Wave optics','Young double slit','In Young double-slit interference, fringe width equals wavelength times screen distance divided by slit separation.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-diffraction-01','optics','Wave optics','Diffraction','Diffraction is the spreading of waves around apertures or obstacles and is strongest when their size is comparable to the wavelength.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-polarisation-01','optics','Wave optics','Polarisation','Polarisation restricts the electric-field vibration direction and demonstrates the transverse nature of light.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-photoelectric-effect-01','modern-physics','Dual nature','Photoelectric effect','Photoelectric emission occurs only above a threshold frequency, while maximum electron kinetic energy depends on frequency rather than intensity.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-einstein-photoelectric-01','modern-physics','Dual nature','Einstein equation','Einstein photoelectric equation states that photon energy equals the work function plus the maximum kinetic energy of an emitted electron.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-photon-momentum-01','modern-physics','Dual nature','Photon momentum','A photon of wavelength lambda has momentum h divided by lambda even though its rest mass is zero.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-de-broglie-01','modern-physics','Dual nature','de Broglie wavelength','The de Broglie wavelength of a particle equals Planck constant divided by its momentum.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-davisson-germer-01','modern-physics','Dual nature','Davisson-Germer experiment','Electron diffraction in the Davisson-Germer experiment confirmed the wave nature and de Broglie wavelength of matter.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-rutherford-model-01','modern-physics','Atoms','Rutherford model','Rutherford scattering showed that most atomic mass and positive charge are concentrated in a very small nucleus.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-bohr-model-01','modern-physics','Atoms','Bohr model','The Bohr model permits stationary electron orbits with quantised angular momentum and radiation only during transitions.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-hydrogen-spectrum-01','modern-physics','Atoms','Hydrogen spectrum','Hydrogen spectral lines arise when an electron transitions between quantised energy levels and emits or absorbs a photon.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-energy-levels-01','modern-physics','Atoms','Energy levels','Bound atomic energy levels are discrete, and the photon energy for a transition equals the magnitude of the level difference.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-nuclear-size-01','modern-physics','Nuclei','Nuclear size','Nuclear radius is approximately proportional to the cube root of mass number.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-binding-energy-01','modern-physics','Nuclei','Mass defect and binding energy','Nuclear binding energy equals the mass defect multiplied by the square of the speed of light.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-radioactive-decay-01','modern-physics','Nuclei','Radioactive decay','The number of undecayed nuclei decreases exponentially with time, with half-life equal to ln 2 divided by the decay constant.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-fission-fusion-01','modern-physics','Nuclei','Fission and fusion','Fission splits a heavy nucleus while fusion combines light nuclei; both can release energy by increasing binding energy per nucleon.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-energy-bands-01','modern-physics','Semiconductors','Energy bands','The size of the forbidden energy gap distinguishes conductors, semiconductors and insulators in band theory.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-intrinsic-extrinsic-01','modern-physics','Semiconductors','Intrinsic and extrinsic semiconductors','Doping an intrinsic semiconductor produces n-type material with majority electrons or p-type material with majority holes.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-pn-junction-01','modern-physics','Semiconductors','p-n junction','A p-n junction forms a depletion region and conducts readily in forward bias but only weakly in reverse bias before breakdown.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-diodes-01','modern-physics','Semiconductors','Diodes','A semiconductor diode mainly permits current in one direction and is used for rectification.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-transistors-01','modern-physics','Semiconductors','Transistors','A transistor uses a small input current or voltage to control a larger output and can act as an amplifier or switch.','standard',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-logic-gates-01','modern-physics','Semiconductors','Logic gates','Logic gates implement Boolean operations such as AND, OR and NOT using binary voltage levels.','foundation',array['jee-main','tg-eapcet','ap-eapcet']),
('physics-instrument-reading-01','modern-physics','Experimental skills','Instrument reading','A valid instrument reading includes the main-scale value, any subsidiary-scale contribution and the correct least-count precision.','foundation',array['jee-main']),
('physics-graph-interpretation-01','modern-physics','Experimental skills','Graph interpretation','The slope and intercept of a correctly scaled graph can reveal physical parameters and test the predicted relation between variables.','foundation',array['jee-main']),
('physics-circuit-experiments-01','modern-physics','Experimental skills','Circuit experiments','Reliable circuit experiments use correct polarity and ranges, tight connections and repeated readings while limiting heating.','foundation',array['jee-main']),
('physics-error-estimation-01','modern-physics','Experimental skills','Error estimation','For independent small uncertainties in products or quotients, fractional uncertainties are added to estimate the maximum fractional uncertainty.','standard',array['jee-main'])
), prepared as (
  select s.*, mod(abs(hashtext(s.slug)),4) as answer_position,
    (select array_agg(fact order by ord) from (select d.fact,row_number() over(order by md5(s.slug||d.slug)) ord from seed d where d.slug<>s.slug limit 3) x) distractors
  from seed s
), rows as (
  select *, case answer_position
    when 0 then jsonb_build_array(fact,distractors[1],distractors[2],distractors[3])
    when 1 then jsonb_build_array(distractors[1],fact,distractors[2],distractors[3])
    when 2 then jsonb_build_array(distractors[1],distractors[2],fact,distractors[3])
    else jsonb_build_array(distractors[1],distractors[2],distractors[3],fact) end options
  from prepared
)
insert into public.juniors_questions(slug,subject,chapter_slug,topic,subtopic,prompt,options,correct_option,explanation,difficulty,exam_tags,status,source_reference,validated_at,validated_by,content_version)
select slug,'physics',chapter_slug,topic,subtopic,'Which statement correctly describes '||subtopic||'?',options,answer_position,fact,difficulty,tags,'published','NCERT Physics XI-XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'
from rows
on conflict(slug) do update set subject=excluded.subject,chapter_slug=excluded.chapter_slug,topic=excluded.topic,subtopic=excluded.subtopic,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,difficulty=excluded.difficulty,exam_tags=excluded.exam_tags,status=excluded.status,source_reference=excluded.source_reference,validated_at=excluded.validated_at,validated_by=excluded.validated_by,content_version=excluded.content_version,updated_at=now();
